def dispatch(state, event):
    if event["type"] == "input":
        state["fields"][event["target"]] = event["value"]
    f = state["fields"]
    errors = {}
    if "@" not in f["email"] or "." not in f["email"]:
        errors["email"] = "invalid"
    if len(f["password"]) < 8:
        errors["password"] = "too_short"
    if f["confirm"] != f["password"]:
        errors["confirm"] = "mismatch"
    state["errors"] = errors
    state["can_submit"] = (len(errors) == 0)
    return state

def main():  # << START_OF_TRACE
    state = {'fields': {'email': 'x@y', 'password': 'abcdefgh', 'confirm': ''}, 'errors': {'email': 'invalid', 'confirm': 'mismatch'}, 'can_submit': False}
    state = dispatch(state, {'type': 'input', 'target': 'password', 'value': 'short'})
    return state

